# Standard library
import uuid

# Third-party
from sqlalchemy import ForeignKey, Integer, JSON, func
from sqlalchemy.orm import Mapped, mapped_column

# Local application
from app.core.base import Base, TimestampMixin


class ExplorerSubConditions(TimestampMixin, Base):
    __tablename__ = "explorer_sub_conditions"

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True,
        server_default=func.gen_random_uuid(),
        description=(
            "Primary key UUID, auto-generated by the database using "
            "gen_random_uuid()."
        ),
    )
    temperature_avg: Mapped[int | None] = mapped_column(
        Integer,
        description=(
            "Average air temperature in degrees Celsius during the activity."
        ),
    )
    temperature_min: Mapped[int | None] = mapped_column(
        Integer,
        description=(
            "Minimum air temperature in degrees Celsius recorded during the "
            "activity."
        ),
    )
    temperature_max: Mapped[int | None] = mapped_column(
        Integer,
        description=(
            "Maximum air temperature in degrees Celsius recorded during the "
            "activity."
        ),
    )
    equipment_used: Mapped[dict | None] = mapped_column(
        JSON,
        description=(
            "JSONB list of equipment and gear items actually used during the "
            "activity, stored as structured data."
        ),
    )
    visibility_id: Mapped[uuid.UUID | None] = mapped_column(
        ForeignKey("core_ref_visibility.id"),
        description=(
            "FK to core_ref_visibility. Categorizes the visibility conditions "
            "(e.g. clear, foggy, poor) during the activity."
        ),
    )
    snow_condition_id: Mapped[uuid.UUID | None] = mapped_column(
        ForeignKey("core_ref_snow_condition.id"),
        description=(
            "FK to core_ref_snow_condition. Categorizes snow conditions (e.g. "
            "powder, icy, none) encountered during the activity."
        ),
    )
    trail_condition_id: Mapped[uuid.UUID | None] = mapped_column(
        ForeignKey("core_ref_trail_condition.id"),
        description=(
            "FK to core_ref_trail_condition. Categorizes the trail surface "
            "condition (e.g. dry, muddy, wet) during the activity."
        ),
    )
    weather_condition_id: Mapped[uuid.UUID | None] = mapped_column(
        ForeignKey("core_ref_weather_condition.id"),
        description=(
            "FK to core_ref_weather_condition. Categorizes the overall "
            "weather (e.g. sunny, rainy, stormy) during the activity."
        ),
    )
